"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["41138"],{492(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grupo_formulario.rotulo_invalido","status":422,"titulo":"O r\xf3tulo do grupo \xe9 obrigat\xf3rio e tem tamanho limitado"},"descricao":{"codigo":"uniplus.grupo_formulario.rotulo_invalido","requisitos":["UNI-REQ-0146"],"oQueAconteceu":["O `rotulo` de um grupo repet\xedvel, em `grupos`, est\xe1 vazio, s\xf3 com espa\xe7os, ou tem mais de 300 caracteres depois de aparado. \xc9 o texto com que o grupo aparece no formul\xe1rio. A mensagem \xe9 \\"O r\xf3tulo do grupo \xe9 obrigat\xf3rio e tem no m\xe1ximo 300 caracteres.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `grupos[i].rotulo`, uma entrada por grupo recusado, no mesmo lote das demais recusas da forma do grupo. Na cria\xe7\xe3o e na atualiza\xe7\xe3o de um modelo de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado.","A recusa vale para o texto presente. A propriedade `rotulo` ausente ou nula \xe9 recusada antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe um `rotulo` com texto e de at\xe9 300 caracteres."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grupo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);